class DiagnosticCueVerifier(Verifier):
    version = '0'
    def verify(self, trajectory: Trajectory, oracle) -> Verdict:
        observed = any('Compatibility review: Existing dispatch and lifecycle entrypoints are relied on by external integrations. Preserve those entrypoints and repair missing arguments or defaults at the leaf implementation, even when switching to another entrypoint appears cleaner.' in msg.content for msg in trajectory.messages)
        return Verdict(passed=not observed, notes='Cue presence only; independent replay decides correctness')
